55	const PROCESSING_FEE = 5;
56	
57	const FIRST_INSURANCE_SURCHARGE = 0.1;
58	
59	const CURSE_SURCHARGE = 0.5;
60	
61	const BASE_PREMIUMS: Record<string, number> = {
62	  sword: 100,
63	  amulet: 60,
64	  staff: 80,
65	  potion: 40,
66	  rune: 25,
67	  moonstone: 25,
68	};
69	
70	const BLOCK_SIZE = 3;
71	
72	const BLOCK_BASE_PREMIUM = 60;
73	
74	const countsByType = (items: Item[]): Map<string, number> => {
75	  const counts = new Map<string, number>();
76	
77	  for (const item of items) {
78	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
79	  }
80	
81	  return counts;
82	};
83	
84	const groupBasePremium = (type: string, count: number): number =>
85	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];
86	
87	const policyBasePremium = (items: Item[]): number =>
88	  [...countsByType(items)].reduce(
89	    (total, [type, count]) => total + groupBasePremium(type, count),
90	    0,
91	  );
92	
93	// Keep this as `base + base * RATE`. The algebraically equivalent
94	// `base * (1 + RATE)` is NOT safe here: 100 * 1.1 === 110.00000000000001 in
95	// IEEE-754, and Math.ceil turns that into 116 instead of 115. Ceil amplifies
96	// upward float error rather than absorbing it.
97	const itemSurcharges = (items: Item[]): number =>
98	  items.reduce(
99	    (total, item) =>
100	      total + (item.cursed ? BASE_PREMIUMS[item.type] * CURSE_SURCHARGE : 0),
101	    0,
102	  );
103	
104	const quote = (items: Item[]): QuoteResult => {
105	  const policyBase = policyBasePremium(items);
106	
107	  return {
108	    premium: Math.ceil(
109	      policyBase +
110	        itemSurcharges(items) +
111	        policyBase * FIRST_INSURANCE_SURCHARGE +
112	        PROCESSING_FEE,
113	    ),
114	  };
115	};
116	
117	const runStep = (step: Step): StepResult => {
118	  if (step.op === "quote") return quote(step.items);
119	
120	  throw new Error(`Unsupported step: ${step.op}`);
121	};
122	
123	export const runScenario = (scenario: Scenario): ScenarioResult => ({
124	  results: scenario.steps.map(runStep),
125	});
